(()=>{const stops=[...document.querySelectorAll('.journey-stop')];const stories=[['01 / BOULDER, CO','Chemical engineering school','Sko Buffs!'],['02 / BEND, OR','The start of pharmaceutical engineering','Lonza'],['03 / LONDON, UK','Across the Atlantic','Pilot plant transfer'],['04 / SEATTLE, WA','The next chapter','My time at Invert'],['05 / PORTLAND, OR','Where I am now','Seeq']];const panel=document.querySelector('#journey-story');function select(i){stops.forEach((b,n)=>{b.classList.toggle('active',n===i);b.setAttribute('aria-pressed',String(n===i))});panel.querySelector('span').textContent=stories[i][0];panel.querySelector('h3').textContent=stories[i][1];panel.querySelector('p').textContent=stories[i][2]}stops.forEach((b,i)=>{b.addEventListener('pointerenter',e=>{if(e.pointerType!=='touch')select(i)});b.addEventListener('focus',()=>select(i));b.addEventListener('click',()=>select(i));b.addEventListener('keydown',e=>{let n=i;if(e.key==='ArrowRight')n=(i+1)%stops.length;else if(e.key==='ArrowLeft')n=(i+stops.length-1)%stops.length;else if(e.key==='Home')n=0;else if(e.key==='End')n=stops.length-1;else return;e.preventDefault();stops[n].focus()})})})();
